const input = document.querySelector('#src');
const tree = document.querySelector('#tree');
const count = document.querySelector('#count');

function row(depth, label, kind) {
  const li = document.createElement('li');
  li.className = 'node ' + kind;
  li.style.paddingLeft = depth * 16 + 'px';
  li.textContent = label;
  return li;
}

function walk(node, depth, rows) {
  if (node.nodeType === Node.ELEMENT_NODE) {
    const tag = node.tagName.toLowerCase();
    const r = row(depth, '<' + tag + '>', 'el');
    if (tag === 'tbody' && !input.value.includes('<tbody')) r.classList.add('new');
    rows.push(r);
  } else if (node.nodeType === Node.TEXT_NODE && node.textContent.trim()) {
    rows.push(row(depth, '"' + node.textContent.trim() + '"', 'txt'));
  }
  for (const child of node.childNodes) walk(child, depth + 1, rows);
}

function render() {
  // DOMParser builds an inert document: no scripts run and no images load.
  const doc = new DOMParser().parseFromString(input.value, 'text/html');
  const rows = [];
  walk(doc.body, 0, rows);
  tree.replaceChildren(...rows);
  const n = doc.body.querySelectorAll('*').length;
  count.textContent = n + ' elements';
  return n;
}

input.addEventListener('input', render);
console.log('Parsed', render(), 'elements. Highlighted: nodes the parser added.');

