const box = document.querySelector('#box');
const why = document.querySelector('#why');
const chips = document.querySelectorAll('#stages li');

// Typical costs in Chromium, Firefox and Safari (engines can optimise further).
const changes = {
  width: { stages: ['style', 'layout', 'paint', 'composite'],
    apply: () => { box.style.width = box.style.width === '220px' ? '160px' : '220px'; },
    text: 'Width changes geometry, so layout runs, then paint and composite.' },
  color: { stages: ['style', 'paint', 'composite'],
    apply: () => { box.style.backgroundColor = box.style.backgroundColor ? '' : '#db2777'; },
    text: 'Colour does not move anything: no layout, but the pixels must be repainted.' },
  transform: { stages: ['style', 'composite'],
    apply: () => { box.style.transform = box.style.transform ? '' : 'translateX(120px) rotate(-4deg)'; },
    text: 'transform moves an already painted layer: usually composite only.' },
  reset: { stages: [], apply: () => box.removeAttribute('style'), text: 'Back to the start.' },
};

document.querySelector('#controls').addEventListener('click', (event) => {
  const btn = event.target.closest('button');
  if (!btn) return;
  const change = changes[btn.dataset.change];
  change.apply();
  chips.forEach((chip) => chip.classList.toggle('on', change.stages.includes(chip.dataset.stage)));
  why.textContent = change.text;
  console.log(btn.dataset.change, '→', change.stages.join(' → ') || 'nothing');
});
document.querySelector('[data-change="width"]').click();

console.log('1. script runs, readyState =', document.readyState);

document.addEventListener('DOMContentLoaded', () => {
  console.log('2. DOMContentLoaded, readyState =', document.readyState);
});

window.addEventListener('load', () => {
  console.log('3. load, readyState =', document.readyState);
});

console.log('   (still inside the script: listeners are only registered)');

