const list = document.getElementById('list');
const input = document.querySelector('#selector');
const count = document.querySelector('#count');
const error = document.querySelector('#error');

function highlight(selector) {
  list.querySelectorAll('.hit').forEach((el) => el.classList.remove('hit'));
  error.hidden = true;
  let matches;
  try {
    matches = list.querySelectorAll(selector);
  } catch (err) {
    error.textContent = err.name + ': "' + selector + '" is not a valid selector.';
    error.hidden = false;
    count.textContent = 'error';
    return;
  }
  // Highlight the whole product card, even when the match is a child.
  matches.forEach((el) => el.closest('.product')?.classList.add('hit'));
  count.textContent = matches.length + (matches.length === 1 ? ' match' : ' matches');
  console.log(selector, '→', matches.length, 'match(es)');
}

document.querySelector('#query').addEventListener('submit', (event) => {
  event.preventDefault();
  highlight(input.value);
});
document.querySelector('#examples').addEventListener('click', (event) => {
  const btn = event.target.closest('button');
  if (!btn) return;
  input.value = btn.textContent;
  highlight(input.value);
});
highlight(input.value);

