const rows = document.querySelector('#rows');
const inspector = document.querySelector('#inspector');

// A short label like 'span.badge.paid' or 'td'.
function describe(el) {
  if (!el) return 'null';
  const classes = [...el.classList].map((c) => '.' + c).join('');
  return el.tagName.toLowerCase() + classes;
}

rows.addEventListener('click', (event) => {
  const target = event.target;
  const row = target.closest('tr');
  if (!row) return;
  rows.querySelector('.selected')?.classList.remove('selected');
  row.classList.add('selected');

  const cell = target.closest('td');
  const facts = [
    ['event.target', describe(target)],
    ["closest('tr').dataset.id", row.dataset.id],
    ['target.parentElement', describe(target.parentElement)],
    ['cell.previousElementSibling', cell.previousElementSibling?.textContent ?? 'null'],
    ['cell.nextElementSibling', describe(cell.nextElementSibling)],
    ['row.children.length', String(row.children.length)],
    ["target.matches('.link')", String(target.matches('.link'))],
  ];
  const dl = document.createElement('dl');
  for (const [label, value] of facts) {
    const dt = document.createElement('dt');
    const dd = document.createElement('dd');
    dt.textContent = label;
    dd.textContent = value;
    dl.append(dt, dd);
  }
  inspector.replaceChildren(dl);
  console.log('Clicked', describe(target), 'in order', row.dataset.id);
});

rows.querySelector('tr:nth-child(2) .link').click();

