const root = document.documentElement;
const buttons = document.querySelectorAll('[data-choice]');
const statusEl = document.querySelector('#status');
const prefersDark = matchMedia('(prefers-color-scheme: dark)');

function applyTheme(choice) {
  const resolved = choice === 'system' ? (prefersDark.matches ? 'dark' : 'light') : choice;
  root.dataset.theme = resolved;                 // <html data-theme="dark">
  buttons.forEach((btn) => {
    const selected = btn.dataset.choice === choice;
    btn.classList.toggle('active', selected);
    btn.setAttribute('aria-checked', String(selected));
  });
  statusEl.textContent = `Saved “${choice}” · showing the ${resolved} theme`;
  localStorage.setItem('ralfiz-theme', choice);
  const bg = getComputedStyle(root).getPropertyValue('--bg').trim();
  console.log('data-theme =', root.getAttribute('data-theme'), '| --bg =', bg);
}

buttons.forEach((btn) => {
  btn.addEventListener('click', () => applyTheme(btn.dataset.choice));
});
applyTheme(localStorage.getItem('ralfiz-theme') ?? 'light');

