const inr = new Intl.NumberFormat('en-IN', {
  style: 'currency', currency: 'INR', maximumFractionDigits: 0,
});
const billing = document.querySelector('#billing');

function setBilling(period) {
  for (const plan of document.querySelectorAll('.plan')) {
    const perMonth = Number(plan.dataset[period]);  // data-monthly / data-yearly
    plan.querySelector('.amount').textContent = perMonth === 0 ? 'Free' : inr.format(perMonth);
    plan.querySelector('.per').textContent = perMonth === 0 ? '' : '/mo';
    plan.querySelector('.note').textContent = perMonth === 0 ? 'Forever'
      : period === 'yearly' ? `Billed ${inr.format(perMonth * 12)} yearly` : 'Billed monthly';
  }
  for (const btn of billing.querySelectorAll('button')) {
    btn.setAttribute('aria-pressed', String(btn.dataset.period === period));
  }
  document.body.dataset.billing = period;
  console.log('billing =', period, '| Pro shows', document.querySelector('.featured .amount').textContent);
}

billing.addEventListener('click', (event) => {
  const btn = event.target.closest('button');
  if (btn) setBilling(btn.dataset.period);
});
setBilling('yearly');

