const input = document.querySelector('#comment');
const safe = document.querySelector('#safe');
const parsed = document.querySelector('#parsed');

function item(text, bad = false) {
  const li = document.createElement('li');
  li.textContent = text;
  li.classList.toggle('bad', bad);
  return li;
}

function update() {
  const text = input.value;
  safe.textContent = text;   // safe: tags become visible characters

  // Inspection only: <template> content is inert (no images load, no handlers run).
  const tpl = document.createElement('template');
  tpl.innerHTML = text;
  const items = [];
  for (const el of tpl.content.querySelectorAll('*')) {
    items.push(item('<' + el.localName + '> element'));
    for (const attr of el.attributes) {
      const risky = attr.name.startsWith('on') || /^\s*javascript:/i.test(attr.value);
      items.push(item(`  ${attr.name}="${attr.value}"${risky ? '  ← runs code!' : ''}`, risky));
    }
  }
  if (items.length === 0) items.push(item('Only text: nothing to worry about.'));
  parsed.replaceChildren(...items);
  console.log('textContent children:', safe.children.length, '| elements innerHTML would create:',
    tpl.content.querySelectorAll('*').length);
}

input.addEventListener('input', update);
update();

