  root.style.setProperty('--hue', hue.value);
  root.style.setProperty('--radius', radius.value + 'px');
  document.querySelector('#hue-out').textContent = hue.value;
  document.querySelector('#radius-out').textContent = radius.value + 'px';

  const computed = getComputedStyle(buy);
  readout.textContent = [
    `html style attribute:  ${root.getAttribute('style')}`,
    `buy.style.background:  "${buy.style.background}"   (no inline style)`,
    `computed background:   ${computed.backgroundColor}`,
    `computed radius:       ${computed.borderRadius}`,
  ].join('\n');
}

