const grid = document.querySelector('#grid');
const quick = document.querySelector('#quick');

function openQuickView(card, cause) {
  for (const c of grid.querySelectorAll('.card')) {
    c.classList.toggle('selected', c === card);
  }
  const big = document.createElement('div');
  big.className = 'big';
  big.textContent = card.querySelector('.thumb').textContent;
  const info = document.createElement('div');
  const title = document.createElement('h4');
  title.textContent = `Quick view: ${card.querySelector('h3').textContent}`;
  const why = document.createElement('p');
  why.append('Opened by a click on ');
  const code = document.createElement('code');
  code.textContent = cause;
  why.append(code);
  info.append(title, why);
  quick.replaceChildren(big, info);
}

grid.addEventListener('click', (event) => {
  // 1. The heart is handled here and we STOP: no stopPropagation needed
  const fav = event.target.closest('.fav');
  if (fav) {
    const saved = fav.getAttribute('aria-pressed') !== 'true';
    fav.setAttribute('aria-pressed', String(saved));
    fav.textContent = saved ? '♥' : '♡';
    console.log(saved ? 'saved to wishlist' : 'removed from wishlist');
    return;
  }

  // 2. Links: cancel navigation, but the event keeps bubbling to the grid
  const link = event.target.closest('a');
  if (link) {
    event.preventDefault();
    console.log('link default prevented; defaultPrevented =',
      event.defaultPrevented);
  }

  // 3. Anything else inside a card opens the quick view
  const card = event.target.closest('.card');
  if (card) openQuickView(card, `<${event.target.localName}>`);
});

grid.querySelector('.card h3').click(); // start with one card open

