const KEY = 'academy:prefs:v1'; // version the key: change the shape → v2
const DEFAULTS = { theme: 'light', speed: '1', autoplay: true, remember: true };
const form = document.querySelector('#prefs');

// Read: whichever store has it. Merge with DEFAULTS so new fields get a value.
function loadPrefs() {
  for (const store of [localStorage, sessionStorage]) {
    try {
      const raw = store.getItem(KEY);
      if (raw) return { ...DEFAULTS, ...JSON.parse(raw) };
    } catch {
      store.removeItem(KEY); // corrupted: forget it
    }
  }
  return { ...DEFAULTS };
}

// Write: "remember me" decides WHERE it is kept
function savePrefs(prefs) {
  const [keep, drop] = prefs.remember
    ? [localStorage, sessionStorage]
    : [sessionStorage, localStorage];
  try {
    keep.setItem(KEY, JSON.stringify(prefs));
    drop.removeItem(KEY);
  } catch (err) {
    console.warn('Not saved:', err.name); // e.g. QuotaExceededError
  }
}

function apply(prefs) {
  form.elements.theme.value = prefs.theme;
  form.elements.speed.value = prefs.speed;
  form.elements.autoplay.checked = prefs.autoplay;
  form.elements.remember.checked = prefs.remember;
  document.querySelector('#app').classList.toggle('dark', prefs.theme === 'dark');
  document.querySelector('#where').textContent =
    `${prefs.remember ? 'localStorage' : 'sessionStorage'}["${KEY}"]`;
}

function readForm() {
  const f = form.elements;
  return { theme: f.theme.value, speed: f.speed.value,
    autoplay: f.autoplay.checked, remember: f.remember.checked };
}

form.addEventListener('change', () => {
  const prefs = readForm();
  savePrefs(prefs);
  apply(prefs);
  const time = new Intl.DateTimeFormat('en-IN', { timeStyle: 'short' }).format(new Date());
  document.querySelector('#saved').textContent = `✓ Saved ${time}`;
  console.log('saved', JSON.stringify(prefs));
});

document.querySelector('#reset').addEventListener('click', () => {
  localStorage.removeItem(KEY);
  sessionStorage.removeItem(KEY);
  apply(DEFAULTS);
  document.querySelector('#saved').textContent = 'Defaults restored';
});

const prefs = loadPrefs();
apply(prefs);
console.log('loaded', JSON.stringify(prefs));

