const CATALOG = [
  { id: 11, icon: '🎧', title: 'Buds Pro', price: 6499 },
  { id: 12, icon: '⌚', title: 'Watch S', price: 8999 },
  { id: 13, icon: '🔋', title: 'Power Bank', price: 1799 },
  { id: 14, icon: '⌨️', title: 'Keyboard', price: 3499 },
  { id: 15, icon: '🖱️', title: 'Mouse', price: 1299 },
  { id: 16, icon: '🔊', title: 'Speaker', price: 4599 },
];
const KEY = 'store:recent:v1';
const MAX = 4;
const inr = new Intl.NumberFormat('en-IN', {
  style: 'currency', currency: 'INR', maximumFractionDigits: 0,
});
const ago = new Intl.RelativeTimeFormat('en', { numeric: 'auto' });

// Store only ids and times: small, and never stale product data
function readRecent() {
  try {
    const list = JSON.parse(localStorage.getItem(KEY) ?? '[]');
    return Array.isArray(list) ? list : [];
  } catch {
    return [];
  }
}

function addRecent(id) {
  const next = [{ id, at: Date.now() }, ...readRecent().filter((r) => r.id !== id)]
    .slice(0, MAX); // most recent first, no duplicates, capped
  localStorage.setItem(KEY, JSON.stringify(next));
  return next;
}

function timeAgo(ms) {
  const minutes = Math.round((ms - Date.now()) / 60000);
  return Math.abs(minutes) < 60
    ? ago.format(minutes, 'minute')
    : ago.format(Math.round(minutes / 60), 'hour');
}

function renderRecent(list) {
  const items = list
    .map((r) => ({ ...r, product: CATALOG.find((p) => p.id === r.id) }))
    .filter((r) => r.product) // ids that no longer exist are skipped
    .map(({ product, at }) => {
      const li = document.createElement('li');
      const ico = document.createElement('span');
      ico.className = 'ico';
      ico.textContent = product.icon;
      const t = document.createElement('div');
      t.className = 't';
      t.textContent = product.title;
      const small = document.createElement('small');
      small.textContent = `${inr.format(product.price)} · ${timeAgo(at)}`;
      t.append(small);
      li.append(ico, t);
      return li;
    });
  document.querySelector('#recent').replaceChildren(...items);
  document.querySelector('#empty').hidden = items.length > 0;
}

const grid = document.querySelector('#products');
grid.append(...CATALOG.map((p) => {
  const b = document.createElement('button');
  b.className = 'product';
  b.dataset.id = p.id;
  b.innerHTML = '<div class="art" aria-hidden="true"></div><b></b><span></span>';
  b.querySelector('.art').textContent = p.icon;
  b.querySelector('b').textContent = p.title;
  b.querySelector('span').textContent = inr.format(p.price);
  return b;
}));

grid.addEventListener('click', (e) => {
  const card = e.target.closest('.product');
  if (!card) return;
  const list = addRecent(Number(card.dataset.id));
  renderRecent(list);
  console.log('stored:', localStorage.getItem(KEY));
});

document.querySelector('#clear').addEventListener('click', () => {
  localStorage.removeItem(KEY);
  renderRecent([]);
});

// First visit: seed two views so the panel is not empty
if (localStorage.getItem(KEY) === null) {
  localStorage.setItem(KEY, JSON.stringify([
    { id: 13, at: Date.now() - 5 * 60000 }, { id: 11, at: Date.now() - 2 * 3600000 },
  ]));
}
renderRecent(readRecent());

