document.documentElement.classList.add('js');
const blocks = document.querySelectorAll('.reveal');
const watch = document.querySelector('#watch');
let watching = 0;
const show = () => { watch.textContent = 'Observing ' + watching + ' blocks'; };

const observer = new IntersectionObserver((entries, obs) => {
  for (const entry of entries) {
    if (!entry.isIntersecting) continue;
    entry.target.classList.add('in');
    obs.unobserve(entry.target);           // reveal once, then stop watching
    watching--;
    console.log('revealed', entry.target.querySelector('h2')?.textContent ?? entry.target.className,
      '· ratio', entry.intersectionRatio.toFixed(2));
  }
  show();
  if (watching === 0) obs.disconnect();
}, {
  threshold: 0.15,                          // 15% visible
  rootMargin: '0px 0px -40px 0px',          // ignore the last 40px of the viewport
});

blocks.forEach((el, i) => {
  el.style.setProperty('--i', i % 3);       // small stagger per row
  observer.observe(el);
  watching++;
});
show();

