const frame = document.querySelector('#frame');
const widget = document.querySelector('#widget');
const readout = document.querySelector('#readout');

const DAYS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
const SALES = [52, 61, 48, 70, 88, 96, 67];
widget.querySelector('.bars').append(...SALES.map((v, i) => {
  const li = document.createElement('li');
  li.style.height = v + '%';
  li.title = DAYS[i] + ': ' + v + 'k';
  li.innerHTML = '<span></span>';
  li.firstChild.textContent = DAYS[i];
  return li;
}));

const sizeFor = (w) => (w < 280 ? 'sm' : w < 470 ? 'md' : 'lg');

// Watch the frame: its height is fixed, so changing the layout inside it
// cannot resize the observed box again (no ResizeObserver loop).
const observer = new ResizeObserver((entries) => {
  for (const entry of entries) {
    const width = Math.round(entry.contentBoxSize[0].inlineSize);
    const size = sizeFor(width);
    readout.textContent = width + 'px · ' + size;
    if (widget.dataset.size !== size) {
      widget.dataset.size = size;
      console.log('layout →', size, 'at', width + 'px');
    }
  }
});
observer.observe(frame);

