// ---- pretend third-party widget: it only knows how to add DOM ----
const chatWidget = {
  n: 0,
  people: ['Anu', 'Rahul', 'Fatima', 'Joel', 'Meera'],
  topics: ['Invoice not printing', 'Refund for order #2231', 'Add a new branch', 'Barcode scanner setup'],
  push() {
    const i = this.n++;
    const li = document.createElement('li');
    li.dataset.read = 'false';
    li.innerHTML = '<b></b><span></span><small></small>';
    li.querySelector('b').textContent = this.people[i % 5];
    li.querySelector('span').textContent = this.topics[i % 4];
    li.querySelector('small').textContent = 'just now';
    document.querySelector('#inbox').prepend(li);
  },
};

// ---- our code: react to whatever changes the list ----
const inbox = document.querySelector('#inbox');
const badge = document.querySelector('#badge');
const log = (text) => {
  const li = document.createElement('li');
  li.textContent = text;
  document.querySelector('#log').prepend(li);
};

function updateBadge() {
  const unread = inbox.querySelectorAll('[data-read="false"]').length;
  badge.textContent = unread;
  badge.classList.toggle('zero', unread === 0);
  badge.classList.add('bump');
  setTimeout(() => badge.classList.remove('bump'), 200);
  document.title = unread ? `(${unread}) Support inbox` : 'Support inbox';
}

const options = { childList: true, subtree: true, attributes: true, attributeFilter: ['data-read'] };
const observer = new MutationObserver((records) => {
  const kinds = records.map((r) => r.type === 'attributes' ? r.attributeName : r.type);
  log(`${records.length} record(s): ${[...new Set(kinds)].join(', ')}`);
  updateBadge();                             // one update per batch, not per change
});
observer.observe(inbox, options);

inbox.addEventListener('click', (e) => {
  const li = e.target.closest('li');
  if (li) li.dataset.read = 'true';
});
document.querySelector('#add').onclick = () => chatWidget.push();
document.querySelector('#readall').onclick = () =>
  inbox.querySelectorAll('li').forEach((li) => { li.dataset.read = 'true'; });
document.querySelector('#pause').onclick = (e) => {
  const paused = e.currentTarget.getAttribute('aria-pressed') !== 'true';
  e.currentTarget.setAttribute('aria-pressed', paused);
  if (paused) {
    observer.disconnect();
    log('observer paused: changes are not tracked');
  } else {
    observer.observe(inbox, options);
    updateBadge();                            // catch up on what we missed
    log('observer resumed');
  }
};

// Three tickets arrive in one go, then more over time
chatWidget.push(); chatWidget.push(); chatWidget.push();
setTimeout(() => chatWidget.push(), 700);
setTimeout(() => chatWidget.push(), 1400);
console.log('Watching', inbox.id, 'with', options);

console.log('1. script starts');
setTimeout(() => console.log('4. timeout 0 runs as a task, after microtasks'), 0);
Promise.resolve().then(() => console.log('3. microtask'));

const id = setTimeout(() => console.log('never logged'), 50);
clearTimeout(id);                               // cancelled before it fired

// Extra arguments are passed to the callback
setTimeout((name, qty) => console.log(`5. ${qty} × ${name} added`), 20, 'Pulse Buds', 2);
console.log('2. script ends');

// setInterval promises "about every 100ms", never exactly
const start = performance.now();
let tick = 0;
const timer = setInterval(() => {
  tick++;
  const expected = tick * 100;
  const actual = Math.round(performance.now() - start);
  console.log(`tick ${tick}: expected ${expected}ms, actual ${actual}ms (+${actual - expected})`);
  if (tick === 2) {
    const t = performance.now();
    while (performance.now() - t < 150) {}      // a long task: nothing else can run
    console.warn('tick 2 blocked the main thread for 150ms');
  }
  if (tick === 5) clearInterval(timer);
}, 100);

