const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const cartBtn = document.querySelector('#cart');
const badge = document.querySelector('#count');
const drawer = document.querySelector('#drawer');
let count = 0;

async function fly(fromEl, toEl, emoji) {
  const a = fromEl.getBoundingClientRect();
  const b = toEl.getBoundingClientRect();
  const flyer = Object.assign(document.createElement('span'), { className: 'flyer', textContent: emoji });
  flyer.style.left = a.left + a.width / 2 - 16 + 'px';
  flyer.style.top = a.top + a.height / 2 - 16 + 'px';
  document.body.append(flyer);
  const dx = b.left + b.width / 2 - (a.left + a.width / 2);
  const dy = b.top + b.height / 2 - (a.top + a.height / 2);
  const animation = flyer.animate([
    { transform: 'translate(0, 0) scale(1)' },
    { transform: `translate(${dx * 0.4}px, ${dy - 60}px) scale(1.2)`, offset: 0.4 },
    { transform: `translate(${dx}px, ${dy}px) scale(0.3)`, opacity: 0.4 },
  ], { duration: 650, easing: 'cubic-bezier(.45,0,.55,1)' });
  await animation.finished;                  // a promise: no timeout guessing
  flyer.remove();
}

document.querySelector('.grid').addEventListener('click', async (e) => {
  const btn = e.target.closest('[data-add]');
  if (!btn || btn.classList.contains('added')) return;
  const card = btn.closest('.card');
  btn.classList.add('added');                // CSS transition does the colour
  btn.textContent = 'Added ✓';
  if (!reduce.matches) await fly(card.querySelector('.art'), cartBtn, card.querySelector('.art').textContent);
  count++;
  badge.textContent = count;
  badge.animate([{ transform: 'scale(1)' }, { transform: 'scale(1.5)' }, { transform: 'scale(1)' }],
    { duration: reduce.matches ? 0 : 300, easing: 'ease-out' });
  const li = document.createElement('li');
  li.textContent = card.querySelector('h2').textContent + ' · ' + card.querySelector('p').textContent;
  document.querySelector('#lines .empty')?.remove();
  document.querySelector('#lines').append(li);
  console.log('added', li.textContent);
  setTimeout(() => { btn.classList.remove('added'); btn.textContent = 'Add to cart'; }, 1200);
});

cartBtn.addEventListener('click', () => {
  const open = drawer.classList.toggle('open');
  cartBtn.setAttribute('aria-expanded', String(open));
});
drawer.addEventListener('transitionend', (e) => {
